\documentclass[11pt]{article}
\usepackage[margin=2.5cm]{geometry}
\usepackage{amsmath}

\title{Handout 5: OLS Algebra Refresher}
\author{ECON 410 --- Econometrics I}
\date{November 2026}

\begin{document}
\maketitle

\section{Setup}
We observe $n$ pairs $(X_t, Y_t)$ and fit the simple regression
$Y_t = \beta_0 + \beta_1 X_t + u_t$ by least squares. This handout
collects the algebraic identities you will need for the midterm; the
derivations follow the same steps as in Lecture 9.

\section{Estimator Identities}
The slope and intercept estimators satisfy the pair of normal
equations, and solving them gives the familiar closed forms. The
residual variance and the standard error of the slope then follow
directly from the residuals $\hat{u}_t = Y_t - \hat{\beta}_0 -
\hat{\beta}_1 X_t$.

\begin{alignat}{2}
\hat{\beta}_1 &= \frac{\sum_{t=1}^{n} (X_t - \bar{X})(Y_t - \bar{Y})}
                    {\sum_{t=1}^{n} (X_t - \bar{X})^2}
& \hat{\beta}_0 &= \bar{Y} - \hat{\beta}_1 \bar{X} \\
\hat{\sigma}^2 &= \frac{1}{n-2} \sum_{t=1}^{n} \hat{u}_t^{\,2}
& s_{\hat{\beta}_1} &= \sqrt{\hat{\sigma}^2 \big/ \textstyle\sum_{t=1}^{n} (X_t - \bar{X})^2} \\
R^2 &= 1 - \frac{\sum_{t=1}^{n} \hat{u}_t^{\,2}}{\sum_{t=1}^{n} (Y_t - \bar{Y})^2}
& F &= \frac{R^2 / 1}{(1 - R^2)/(n-2)}
& n &= 142
\end{alignat}

\section{Reading the Output}
The regression table in the statistical package reports each
coefficient with its standard error, the $t$ ratio, and the
$p$ value. The residual degrees of freedom $n - 2$ enter every
inference quantity, so check that the reported sample size matches the
number of usable observations after any missing values are dropped.

\section{Common Pitfalls}
Do not confuse the standard error of the regression $\hat{\sigma}$
with the standard error of the slope; the latter divides by the spread
of the regressor. A wider spread of $X$ around its mean lowers the
variance of $\hat{\beta}_1$, which is why experimental designs spread
the treatment values as widely as ethics and budget allow.

\section{Practice}
Recompute every quantity above for the advertising data set on the
course page, and verify that the $F$ statistic equals the square of
the $t$ ratio on the slope coefficient in simple regression.

\end{document}

